import re

def parse_csv(text):
    lines = text.strip().split('\n')
    if not lines:
        return []

    headers = lines[0].split(',')
    result = []

    for line in lines[1:]:
        # Use regex to handle quoted fields
        values = re.split(r',(?=(?:[^"]*"[^"]*")*[^"]*$)', line)
        row = {headers[i]: values[i] for i in range(len(headers))}
        result.append(row)

    return result

