class TextBuffer {
  constructor(text = '') {
    this.text = text;
    this.history = [];
    this.redoStack = [];
  }

  undo() {
    if (this.history.length === 0) {
      return false;
    }
    const lastEdit = this.history.pop();
    this.redoStack.push(lastEdit);
    this.text = lastEdit.text;
    return true;
  }

  redo() {
    if (this.redoStack.length === 0) {
      return false;
    }
    const nextEdit = this.redoStack.pop();
    this.history.push(nextEdit);
    this.text = nextEdit.text;
    return true;
  }
}

