class TextBuffer {
  constructor() {
    this.buffer = '';
    this.history = [];
  }

  insert(text) {
    this.buffer += text;
    this.history.push({ type: 'insert', text });
  }

  remove(length) {
    const removed = this.buffer.slice(-length);
    this.buffer = this.buffer.slice(0, -length);
    this.history.push({ type: 'remove', length, text: removed });
  }

  getText() {
    return this.buffer;
  }

  redo() {
    if (this.history.length > 0) {
      const last = this.history.pop();
      if (last.type === 'insert') {
        this.insert(last.text);
      } else if (last.type === 'remove') {
        this.remove(last.length);
      }
    }
  }

  undo() {
    if (this.history.length > 0) {
      const last = this.history.pop();
      if (last.type === 'insert') {
        this.remove(last.text.length);
      } else if (last.type === 'remove') {
        this.insert(last.text);
      }
    }
  }

  replaceAll(search, replacement) {
    const originalBuffer = this.buffer;
    let count = 0;
    let pos = this.buffer.indexOf(search);

    while (pos !== -1) {
      this.buffer = this.buffer.slice(0, pos) + replacement + this.buffer.slice(pos + search.length);
      count++;
      pos = this.buffer.indexOf(search, pos + replacement.length);
    }

    this.history.push({ type: 'replaceAll', search, replacement, originalBuffer });
    return count;
  }
}

