def get(data, path, default=None):
    if isinstance(path, str):
        keys = path.split('.')
    else:
        keys = path
    for key in keys:
        if isinstance(data, dict) and key in data:
            data = data[key]
        elif isinstance(data, list) and key.isdigit() and int(key) < len(data):
            data = data[int(key)]
    else:
        return default
    return data

