def delete(path, obj):
    """Delete a value in a nested dictionary by path."""
    keys = path.split('.')
    for key in keys[:-1]:
        if isinstance(obj, dict) and key in obj:
            obj = obj[key]
        else:
            return False
    if isinstance(obj, dict) and keys[-1] in obj:
        del obj[keys[-1]]
        return True
    return False

def diff(a, b):
    """Find the differences between two nested dictionaries."""
    result = {}
    for key in a:
        if key not in b:
            result[key] = a[key]
        elif isinstance(a[key], dict) and isinstance(b[key], dict):
            sub_diff = diff(a[key], b[key])
            if sub_diff:
                result[key] = sub_diff
    for key in b:
        if key not in a:
            result[key] = b[key]
    return result

