def flatten(obj, parent_key='', sep='.'):
    """Flatten a nested dictionary."""
    items = []
    for k, v in obj.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

def get(path, obj):
    """Get a value from a nested dictionary by path."""
    keys = path.split('.')
    for key in keys:
        if isinstance(obj, dict) and key in obj:
            obj = obj[key]
        else:
            return None
    return obj

def set_path(path, value, obj):
    """Set a value in a nested dictionary by path."""
    keys = path.split('.')
    for key in keys[:-1]:
        if isinstance(obj, dict) and key in obj:
            obj = obj[key]
        else:
            obj[key] = {}
            obj = obj[key]
    if isinstance(obj, dict):
        obj[keys[-1]] = value
    return obj

def unflatten(obj, sep='.'):
    """Unflatten a dictionary."""
    result = {}
    for key, value in obj.items():
        keys = key.split(sep)
        set_path(keys, value, result)
    return result

def merge(a, b):
    """
    Deep merge of two dictionaries. Nested dicts merge, anything else from b wins.
    Lists are replaced, not merged. Neither input is changed.
    """
    result = a.copy()
    for key, value in b.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge(result[key], value)
        else:
            result[key] = value
    return result

